#!/usr/bin/env node
// Generates docs/LINES.md (every line code and stop name usable in config) from docs/lines/**/*.json.
import { readdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const LINES_DIR = join(dirname(fileURLToPath(import.meta.url)), '..', 'docs', 'lines')
const TYPES = [
  ['metro', 'Métro'],
  ['tram', 'Tramway'],
  ['bus', 'Bus'],
  ['car', 'Cars lecar / Cartreize (scheduled only, see CAR_LINES.md)'],
]

const out = [
  '# Available lines and stops',
  '',
  '> Generated by `npm run docs:lines` from `docs/lines/**/*.json`. Do not edit by hand.',
  '',
  'Use the **line code** in `public/config.json` (`"line"`) or in the URL (`?lines=`). Codes and stop names are',
  'case- and accent-insensitive; a stop name only needs to be a unique-enough part of the full name',
  '(exact match wins, otherwise the first stop containing the text).',
  '',
  '```',
  '?lines=M1:Castellane,T1:Noailles,B1',
  '```',
  '',
]

const files = []
for (const [type, label] of TYPES) {
  const names = await readdir(join(LINES_DIR, type)).catch(() => [])
  const lines = []
  for (const f of names.filter((n) => n.endsWith('.json'))) {
    lines.push(JSON.parse(await readFile(join(LINES_DIR, type, f), 'utf8')))
  }
  lines.sort((a, b) => a.name.localeCompare(b.name, 'fr', { numeric: true }))
  files.push([type, label, lines])
}

out.push('## Summary', '', '| Type | Line codes |', '| --- | --- |')
for (const [, label, lines] of files) out.push(`| ${label} | ${lines.map((l) => `\`${l.name}\``).join(', ') || '_not scraped yet_'} |`)
out.push('')

for (const [, label, lines] of files) {
  if (!lines.length) continue
  out.push(`## ${label}`, '')
  for (const line of lines) {
    out.push(`### ${line.name}`, '', `API id: \`${line.id}\``, '')
    for (const [destination, routeId] of Object.entries(line.directionIds)) {
      const stops = line.stationIds[routeId] ?? []
      out.push(`**Towards ${destination}** (\`${routeId}\`, ${stops.length} stops):`, '', stops.map((s) => s.Name).join(' → '), '')
    }
  }
}

await writeFile(join(LINES_DIR, '..', 'LINES.md'), out.join('\n'))
console.log('Wrote docs/LINES.md')
